  (gen_random_uuid(), 1, 'Register', 'CPU aynı ara değeri art arda işlemlerde kullanıyor. Bellek erişimini azaltmak için nerede tutarsın?', 'Ara değeri işlemci içindeki uygun bir yazmaçta tutarım.', 'Her kullanımda ana bellekten yeniden okuyup gecikmeyi değişmez kabul ederim.', 'Ara değeri AR''de tutup sonraki bellek adresinin üzerine yazmayı kabul ederim.', 'Değerin hangi yazmaçta olduğunu izlemeden rastgele bir yazmacı kullanırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Register', 'Denetim izi R2 ← R1 mikroişlemini gösteriyor. İşlem sonunda hangi durumu beklersin?', 'R1''in mevcut içeriği R2''ye kopyalanır, R1 korunur.', 'R1 boşaltılır ve yalnızca R2 yeni değeri tutar.', 'R1 ile R2 içerikleri otomatik olarak yer değiştirir.', 'Aktarım yönünü ters okuyup R2''nin eski değerini R1''e yazarım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Clock', 'Bir yazmacın girişinde doğru veri var fakat load sinyali etkin değil. Saat kenarında ne olmasını beklersin?', 'Load etkin olmadığı için yazmacın önceki değerini korumasını beklerim.', 'Girişte veri bulunduğu için yazmacın denetimsiz yükleme yapacağını varsayarım.', 'Saat sinyalinin yazmacı her çevrimde otomatik sıfırladığını kabul ederim.', 'Load koşulunu incelemeden yanlış yazmaç değerini işlem sonucu olarak kullanırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 2, 'Memory', 'AR yazmacındaki adreste bulunan bellek kelimesini DR yazmacına alacaksın. Mikroişlemi nasıl kurarsın?', 'Belleği AR ile adresler ve okunan kelimeyi DR''ye yüklerim.', 'DR içeriğini aynı adrese yazarak bunun okuma işlemi olduğunu varsayarım.', 'AR değerini veri kabul edip bellek erişmeden DR''ye kopyalarım.', 'Adres yazmacını yüklemeden belirsiz bir bellek konumunu okurum.', 'computer_architecture', 1),
  (gen_random_uuid(), 2, 'Memory', 'AC içeriğini AR''nin gösterdiği bellek konumuna kaydedeceksin. Hangi yönü seçersin?', 'Bellek yazmayı etkinleştirip M[AR] ← AC aktarımını uygularım.', 'Bellek okumayı etkinleştirip AC''nin yine belleğe yazılacağını varsayarım.', 'AR içeriğini AC''nin veri değeri olarak belleğe kaydederim.', 'Yazma denetimini adres kararlı olmadan açıp yanlış kelimeyi değiştiririm.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'ALU', 'İki yazmaçtaki sayıyı toplayıp sonucu hedef yazmaca aktaracaksın. Veri yolunda hangi bileşeni kullanırsın?', 'İki girdiyi ALU''nun toplama işlemine verip sonucu hedef yazmaca yüklerim.', 'Multiplexer seçiminin tek başına sayıları toplayacağını varsayarım.', 'İkinci girdiyi seçmeden önceki ALU girişinin korunacağını varsayarım.', 'ALU işlem kodunu belirlemeden çıkan bitleri geçerli toplam sayarım.', 'computer_architecture', 1),
  (gen_random_uuid(), 2, 'ALU', 'Donanımda ayrı çıkarıcı kullanmadan A-B işlemi gerekiyor. Toplayıcı girişlerini nasıl hazırlarsın?', 'B''nin bitlerini tersleyip giriş taşımasını 1 yaparak ikiye tümleyen toplamı kurarım.', 'B''yi yalnızca tersleyip giriş taşımasını 0 bırakarak tam çıkarma yaptığımı varsayarım.', 'A ve B''yi normal toplar, sonucun işaretini değiştiririm.', 'Çıkarma modunda B''yi değiştirmeden yalnızca taşıma çıkışını sonuç sayarım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Shift', 'İşaretsiz bir değeri mantıksal olarak bir bit sağa kaydıracaksın. Sol uçta ne üretirsin?', 'Boşalan en anlamlı bite 0 yerleştiririm.', 'Eski işaret bitini sol uçta koruyup aritmetik kaydırma yaparım.', 'Sağdan çıkan biti sol uca geri bağlayıp dairesel kaydırma uygularım.', 'Kaydırma türünü seçmeden işaretli ve işaretsiz veriyi aynı kuralla işlerim.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Shift', 'İkiye tümleyen işaretli sayıyı ikiye bölmek için sağa kaydıracaksın. İşareti nasıl korursun?', 'Aritmetik sağa kaydırmada eski işaret bitini sol uca yayarım.', 'Sol uca her zaman 0 koyup negatif sayıların işaretini koruduğumu varsayarım.', 'Sağdan çıkan biti işaret biti olarak geri yüklerim.', 'Negatif değeri mantıksal kaydırıp sonucu pozitif sayı olarak kullanırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Instruction', 'Denetim birimi komut kelimesindeki işlemi belirleyecek. Önce hangi alanı çözer?', 'Yapılacak işlemi belirleyen opcode alanını decode ederim.', 'Adres alanını opcode kabul edip bellek konumuna göre işlem seçerim.', 'Adres alanını opcode ile birleştirip tamamını tek denetim kodu gibi yorumlarım.', 'Opcode çözmeden rastgele bir denetim sinyalini etkinleştiririm.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Instruction', 'Bellek-referanslı komutun hangi kelime üzerinde çalışacağını bulacaksın. Hangi alanı kullanırsın?', 'Komutun adres alanını etkin adresi belirleme sürecinde kullanırım.', 'Opcode bitlerini doğrudan bellek adresi kabul ederim.', 'AR''de kalan önceki adresi yeni komutun operand konumu sayarım.', 'Adres alanını okumadan komutu rastgele bir bellek kelimesinde çalıştırırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Register', 'İşlemci sıradaki komutun bellek adresini izlemeli. Hangi yazmacı güncel tutarsın?', 'Sıradaki komut adresini PC yazmacında tutarım.', 'IR yazmacını her zaman sıradaki komut adresi olarak kullanırım.', 'AC içeriğini komut adresi sayarım.', 'PC''yi artırmadan aynı komutu istemeden sürekli yeniden çalıştırırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Register', 'Fetch tamamlandıktan sonra yürütülecek komut bitlerini nerede sabit tutarsın?', 'Alınan komut kelimesini IR yazmacında tutarım.', 'Komut bitlerini yalnızca PC''de tutup adresi kaybederim.', 'Bellekten gelen komutu DR''de tutup IR''nin eski komutta kalmasına izin veririm.', 'IR yüklenmeden eski komutun opcode sinyallerini çalıştırırım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Register', 'Aritmetik komutların ana operandı ve sonucu için temel bilgisayarda hangi yazmacı kullanırsın?', 'Operand ve aritmetik sonuç için AC yazmacını kullanırım.', 'PC yazmacını sonuç deposu yapıp komut akışını da koruduğumu varsayarım.', 'Aritmetik sonucu DR''de bırakıp AC''nin de güncellendiğini varsayarım.', 'Aritmetik sonucu adres yazmacına yazıp sonraki bellek erişimini bozarım.', 'computer_architecture', 1),
  (gen_random_uuid(), 1, 'Control Unit', 'Opcode ve zamanlama bilgisine göre yazmaç yüklemelerini koordine edeceksin. Hangi birim bu sinyalleri üretir?', 'Denetim birimiyle veri yoluna ve yazmaçlara uygun kontrol sinyallerini üretirim.', 'Opcode decoder çıkışlarını zamanlama koşulu olmadan doğrudan bütün load hatlarına bağlarım.', 'ALU sonucunun tek başına komut sırasını belirleyeceğini varsayarım.', 'Birbiriyle çakışan yazma ve yükleme sinyallerini aynı anda etkinleştiririm.', 'computer_architecture', 1),
  (gen_random_uuid(), 2, 'Data Path', 'Ortak veri yoluna aynı çevrimde iki yazmaç çıkışı bağlanıyor. Tasarımı nasıl düzeltirsin?', 'Seçicilerle veri yoluna her anda yalnızca bir kaynak yazmaç bağlarım.', 'İki kaynağın bitlerini elektriksel olarak birleştirip geçerli veri beklerim.', 'Hedef yazmacı kapatarak kaynak çakışmasının ortadan kalkacağını varsayarım.', 'Çıkış çakışmasını bırakıp belirsiz değeri bellek adresi olarak kullanırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Data Path', 'Ortak veri yolunda 16 yazmaçtan birini seçmen gerekiyor. Kaynak seçimi için kaç kontrol biti ayırırsın?', 'On altı seçeneği kodlamak için 4 seçim biti ayırırım.', 'Yalnızca 3 bit ayırıp on altı yazmacın tamamını seçebileceğimi varsayarım.', 'Her veri biti için 16 seçim biti kullanırım.', 'Seçim alanını tanımlamadan birden fazla yazmacı aynı anda veri yoluna sürerim.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Data Path', '32 bitlik ortak veri yolunu bit dilimli multiplexer yapısıyla kuruyorsun. Kaç paralel seçici gerekir?', 'Her veri yolu biti için bir tane olmak üzere 32 multiplexer kullanırım.', 'Tek multiplexer ile 32 biti farklı saatlerde taşıyıp yolu yine paralel sayarım.', 'Yazmaç sayısı kadar multiplexer kullanmanın veri genişliğini belirlediğini varsayarım.', 'Yalnızca alt bitleri bağlayıp üst bitleri tanımsız bırakarak kelimeyi taşırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Register', 'Aynı saat adımında R1''e hem R2 hem R3 yükleme sinyali üretiliyor. Denetimi nasıl güvenli hale getirirsin?', 'Koşulları karşılıklı dışlayıp R1 için tek kaynak seçilmesini sağlarım.', 'İki değerin aynı yazmaçta kendiliğinden birleşeceğini varsayarım.', 'R1 load sinyalini sürekli açık bırakarak öncelik sorununu çözerim.', 'Hangi değerin yüklendiği belirsizken R1''i kritik adres olarak kullanırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'ALU', 'Tek toplayıcıyla hem toplama hem çıkarma yapacaksın. Mod sinyalini veri yoluna nasıl bağlarsın?', 'Çıkarma modunda B bitlerini XOR ile tersler ve giriş taşımasını 1 yaparım.', 'Mod sinyalini yalnızca çıkış taşımasına bağlayıp B girişini değiştirmem.', 'Toplama modunda iki girdiyi de tersleyerek normal toplam beklerim.', 'Mod sinyalinin belirsiz olduğu çevrimde sonucu mimari duruma yazarım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'ALU', 'Signed toplama sonucu yanlış görünüyor fakat carry biti 0. Hata ayıklarken neyi ayırırsın?', 'Unsigned carry ile signed overflow koşullarını ayrı değerlendiririm.', 'Carry 0 olduğu için signed overflow oluşamayacağını varsayarım.', 'Sonucun yalnızca en düşük bitine bakarak taşma kararı veririm.', 'Overflow kontrol etmeden işaret değiştiren sonucu geçerli bakiye olarak kaydederim.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Shift', 'Bir bit deseni sağa döndürülecek ve hiçbir bit kaybolmamalı. Hangi kaydırmayı seçersin?', 'Sağdan çıkan biti sol uca geri veren dairesel sağa kaydırma kullanırım.', 'Mantıksal sağa kaydırıp çıkan biti yok ederek deseni koruduğumu varsayarım.', 'İşaret bitini çoğaltan aritmetik sağa kaydırmayı döndürme sayarım.', 'Kaybolan biti izlemeyip kimlik bit desenini geri döndürülemez biçimde değiştiririm.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Instruction', '24 bitlik komutta 64K kelimelik bellek, 16 yazmaç ve bir dolaylı adres biti kullanılacak. Opcode için kaç bit kalır?', 'Adres için 16, yazmaç için 4 ve dolaylı bit için 1 ayırıp opcode''a 3 bit bırakırım.', '64K adresi 8 bit ile kodlayıp opcode alanını yapay olarak büyütürüm.', 'Yazmaç seçimini 16 bit yapıp adres alanını kaldırırım.', 'Alanların toplamını kelime genişliğinden büyük bırakıp bitlerin üst üste binmesine izin veririm.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Addressing', 'Komutun adres alanı operandın bulunduğu bellek konumunu doğrudan gösteriyor. Operand erişimini nasıl yaparsın?', 'Adres alanını etkin adres kabul edip operandı o bellek konumundan okurum.', 'Adres alanındaki kelimeyi ikinci bir adres kabul edip gereksiz dolaylı erişim yaparım.', 'Adres alanını AC''ye taşıyıp bellek okuması yapmadan operandı elde ettiğimi varsayarım.', 'Adresleme bitini incelemeden her komutu iki bellek okumasıyla yürütürüm.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Addressing', 'Dolaylı adresleme biti açık komutta adres alanı bir işaretçi konumunu gösteriyor. Etkin adresi nasıl bulursun?', 'Önce adres alanının gösterdiği bellek kelimesini okuyup içindeki adresi etkin adres yaparım.', 'Adres alanını doğrudan operand kabul edip işaretçi çözümünü atlarım.', 'İşaretçi konumunu PC''ye yükleyip operand erişimi yerine komut akışını o adrese yönlendiririm.', 'İşaretçi kelimesini gerçek operand sanıp yanlış değeri mimari duruma yazarım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Instruction', 'Fetch çevriminde PC ilerliyor ancak IR eski komutu tutuyor. Mikroişlem sırasını nasıl düzeltirsin?', 'PC adresini AR''ye aktarır, belleği IR''ye okur ve PC''yi sonraki komuta ilerletirim.', 'PC''yi artırıp yeni adresteki kelimeyi yalnızca AR''de komut olarak tutarım.', 'PC arttıktan sonra yeni PC''yi aynı fetch işleminin bellek adresi olarak kullanırım.', 'IR yüklenmeden decode sinyallerini eski komuta göre üretirim.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Control Unit', 'Fetch ve execute mikroişlemlerinin doğru sırada etkinleşmesi gerekiyor. Zaman adımlarını neyle izlersin?', 'Sequence counter ve zaman decoder sinyalleriyle mikroişlem adımlarını sıralarım.', 'Opcode bitlerini saat yerine kullanıp her işlemi aynı anda başlatırım.', 'SC yerine PC''nin alt bitlerini zamanlama decoder girişine bağlarım.', 'Zaman durumunu izlemeyip bellek okuma ve yazmayı rastgele çevrimlerde etkinleştiririm.', 'computer_architecture', 2),
  (gen_random_uuid(), 1, 'Assembly', 'Bir sonraki hesaplamadan önce accumulator değerini sıfırlaman gerekiyor. Hangi temel komut davranışını seçersin?', 'CLA komutuyla AC içeriğini sıfırlarım.', 'CLE komutuyla E bitini temizleyip AC''nin de sıfırlanacağını varsayarım.', 'CMA ile AC bitlerini tersleyerek sıfır üretirim.', 'AC''yi temizlemeden önceki işlemin sonucunu yeni toplama başlangıcı olarak kullanırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 1, 'Assembly', 'Temel bilgisayarda AC değerini bir artırırken taşıma bağlantısını değiştirmemek istiyorsun. Ne yaparsın?', 'INC komutuyla AC''yi bir artırır, E bitini olduğu gibi bırakırım.', 'CME ile E''yi tersleyip AC''nin de artacağını varsayarım.', 'Bellek operandını okumadan ADD komutuyla AC değerinin bir artacağını varsayarım.', 'AC taşmasını izlemeden artırılan değeri adres sınırı olarak kullanırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 2, 'Assembly', 'AC sıfırsa sıradaki komutu atlamak istiyorsun. Hangi yazmaç-referanslı davranışı kullanırsın?', 'SZA koşuluyla AC sıfırken PC''nin bir kez daha artırılmasını sağlarım.', 'SNA kullanıp AC sıfırken negatif kabul edilmesini beklerim.', 'SZE kullanıp AC''nin sıfır durumunu E bitinden sınamaya çalışırım.', 'Koşulu test etmeden PC''yi her çevrimde fazladan artırırım.', 'computer_architecture', 2),
  (gen_random_uuid(), 3, 'Register', 'Tek saat kenarında R1 ile R2 içeriklerini geçici yazmaç kullanmadan değiştireceksin. Donanımı nasıl sürersin?', 'R1 girişine eski R2''yi, R2 girişine eski R1''i bağlayıp iki load sinyalini aynı kenarda etkinleştiririm.', 'Önce R1 ← R2 yapıp aynı çevrimde R2 ← R1 ile eski R1''in korunacağını varsayarım.', 'İki yazmacı aynı ortak veri yolu kaynağına bağlayıp farklı değer yüklerim.', 'Eski değerlerden birini yedeklemeden ardışık yüklemeyle iki yazmacı aynı değere dönüştürürüm.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Control Unit', 'P doğruysa R1←R2, yalnızca P yanlış ve Q doğruysa R1←R3 yapılacak. Load seçimlerini nasıl üretirsin?', 'R2 yolunu P, R3 yolunu P''nin değili ile Q''nun birleşimiyle etkinleştiririm.', 'İki yolu doğrudan P ve Q ile sürüp ikisi 1 olduğunda çakışmayı kabul ederim.', 'P ve Q''yu OR''layıp tek load sinyali üretir, veri kaynağını seçmeden bırakırım.', 'İki kaynak aynı anda seçilebildiği halde R1 sonucunu deterministik kabul ederim.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Memory', 'Tek portlu bellekte aynı çevrimde M[AR] okunup aynı adrese R3 yazılmak isteniyor. Nasıl planlarsın?', 'Okuma ve yazmayı ayrı zaman adımlarına bölüp gerekli ara değeri yazmaçta tutarım.', 'Tek portun aynı anda bağımsız okuma ve yazma yapacağını varsayarım.', 'Adres kararlı olsa bile read ve write denetimlerini sürekli birlikte etkinleştiririm.', 'Okunan değeri doğrulamadan yazmayla ezip geri alınamaz durum kaybı oluştururum.', 'computer_architecture', 3),
  (gen_random_uuid(), 2, 'ALU', 'İki pozitif ikiye tümleyen sayı toplanınca sonuç negatif görünüyor. Overflow denetimini nasıl kurarsın?', 'Girdilerin işareti aynı ve sonuç işareti farklıysa signed overflow üretirim.', 'Yalnızca en üst bitten carry çıkmamasını overflow yokluğu sayarım.', 'Sonuç negatif olduğu için işlemi normal çıkarma olarak yeniden sınıflandırırım.', 'Overflow bayrağını üretmeden negatif sonucu geçerli pozitif toplam olarak kullanırım.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Shift', 'İşaretli sayı aritmetik sola kaydırıldığında işaret biti değişiyor. Sonucu nasıl değerlendirirsin?', 'Temsil aralığı aşıldığı için overflow oluştuğunu işaretlerim.', 'Sola kaydırmada işaret değişimini her zaman geçerli çarpma sonucu sayarım.', 'Aritmetik sola kaydırmanın bütün üst bitleri koruduğunu varsayarım.', 'İşaret değişimini yok sayıp bozulmuş değeri kritik hesapta kullanırım.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Addressing', 'Dolaylı ADD komutu operand yerine işaretçi kelimesini topluyor. Mikroişlem akışını nasıl düzeltirsin?', 'Adres alanını AR''ye alır, M[AR] ile etkin adresi çözer, operandı DR''ye okuyup AC''ye eklerim.', 'IR''nin adres alanını doğrudan DR''ye veri olarak kopyalayıp toplamayı sürdürürüm.', 'Dolaylı biti yok sayıp ilk bellek kelimesini operand kabul ederim.', 'İşaretçiyi finansal operand olarak AC''ye ekleyip yanlış sonucu kalıcılaştırırım.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Addressing', 'Komutun I biti açık olmasına rağmen veri yolu doğrudan adres alanına gidiyor. Hangi hatayı ararsın?', 'Indirect çevrimin ve M[AR] üzerinden etkin adres yüklemesinin atlanıp atlanmadığını kontrol ederim.', 'I bitini opcode''un parçası sayıp doğrudan adreslemeyi sürdürürüm.', 'AR''yi PC''ye aktararak etkin adresi komut akışına yazıp yürütmeyi sürdürürüm.', 'Yanlış bellek kelimesini okuyup adresleme hatasını veri bozulması olarak gizlerim.', 'computer_architecture', 3),
  (gen_random_uuid(), 2, 'Instruction', 'Yeni komut biçimindeki alanların toplamı 32 biti aşıyor. Kodlamayı nasıl düzeltirsin?', 'Alan gereksinimlerini yeniden bütçeler, azaltılamıyorsa komut biçimini açıkça genişletirim.', 'Fazla bitleri sessizce kesip bazı adreslerin yanlış decode edilmesini kabul ederim.', 'Alanları aynı bit konumlarına bindirip bağlama göre kendiliğinden ayrılmasını beklerim.', 'Opcode ve adres bitlerini çakıştırıp farklı komutların aynı kodla çalışmasına izin veririm.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Control Unit', 'Aynı zaman adımında PC için hem yükleme hem artırma denetimi oluşuyor. Belirsizliği nasıl giderirsin?', 'Koşulları karşılıklı dışlayıp çevrimde PC için tek durum güncellemesi seçerim.', 'PC''nin iki işlemi rastgele sırada yapmasını mimari davranış kabul ederim.', 'Clock sinyalini kapatmadan iki denetimi de sürekli etkin tutarım.', 'Belirsiz PC değerini sıradaki komut adresi olarak belleğe gönderirim.', 'computer_architecture', 3),
  (gen_random_uuid(), 3, 'Control Unit', 'Komut tamamlandığı halde SC sıfırlanmadığı için sonraki fetch T0''dan başlamıyor. Ne yaparsın?', 'Komutun son zaman adımında SC clear sinyalini üretip yeni çevrimi T0''dan başlatırım.', 'SC''yi artırmayı sürdürüp decoder''ın kendiliğinden T0 üreteceğini varsayarım.', 'PC''yi sıfırlayarak zamanlama sayacını da sıfırladığımı kabul ederim.', 'Yanlış zaman sinyalleriyle eski komut mikroişlemlerini yeni komutta tekrar çalıştırırım.', 'computer_architecture', 3),
